    const HELPERS: &str = "def add(df):\n    df[\"z\"] = 1\n    return df\n\n\ndef clean(df):\n    return df.dropna()\n\n\ndef fix_in_place(df):\n    df[\"y\"] = 2\n\n\ndef reshape(df):\n    return df.groupby(\"a\").sum()\n";

