        let main_source = "import pandas as pd\nfrom middle import normalize\n\ndf = pd.read_csv(\"a.csv\", usecols=[\"a\"])\nout = normalize(df)\nprint(out[\"z\"])\nprint(df[\"z\"])\n";
        fs::write(root.join("main.py"), main_source).unwrap();

