    fn unknown_column_errors(errors: &[LintError]) -> Vec<(usize, String)> {
        errors
            .iter()
            .filter(|e| e.code == CODE_UNKNOWN_COLUMN)
            .map(|e| (e.line, e.message.clone()))
            .collect()
    }

