    #[test]
    fn test_should_forget_self_frame_facts_after_calls_that_reach_self_without_naming_it() {
        // arrange
        let source = r#"import pandas as pd


class Child:
    def __init__(self, parent):
        self.parent = parent

    def fill(self):
        self.parent.df = self.parent.df.assign(b=1)


class Base:
    def enrich(self):
        self.df = self.df.assign(b=1)


class P(Base):
    def __init__(self):
        self.df = pd.DataFrame({"a": [1]})
        self.child = Child(self)

    def via_child(self):
        self.df = pd.DataFrame({"a": [1]})
        c = self.child
        c.fill()
        return self.df["b"]

    def via_alias(self):
        self.df = pd.DataFrame({"a": [1]})
        obj = self
        obj.df = obj.df.assign(b=2)
        return self.df["b"]

    def via_super(self):
        self.df = pd.DataFrame({"a": [1]})
        super().enrich()
        return self.df["b"]

    def via_closure(self):
        self.df = pd.DataFrame({"a": [1]})

        def add():
            self.df = self.df.assign(b=1)

        add()
        return self.df["b"]

    def via_hooks(self, hooks):
        self.df = pd.DataFrame({"a": [1]})
        for hook in hooks:
            hook()
        return self.df["b"]
"#;

        // act
        let errors = errors_for(source);

        // assert
        assert!(errors.is_empty(), "{errors:?}");
    }

